-- Nuestra Casita v12. Ejecutar UNA VEZ en el proyecto pvxxarxbgmjpaciewmml.
-- Ampliación aditiva: conserva cuentas, compras, fondos y sesiones. Requiere migracion.sql previa.
begin;
alter table public.casas add column if not exists distribucion jsonb not null default '{}'::jsonb;
create or replace function public.nc_estado(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;r jsonb;begin select casa into c from public.miembros where jugador=j;if c is null then raise exception 'Todavía no tienes casa.';end if;perform public.nc_tick(c);select jsonb_build_object('yo',j,'casa',jsonb_build_object('id',h.id,'codigo',h.codigo,'canal',h.canal,'dinero',h.dinero,'amor',h.amor,'compras',h.compras,'distribucion',h.distribucion,'dia',h.dia,'segundos',mod(extract(epoch from(now()-h.creada))::numeric,2160)),'jugadores',(select jsonb_agg(jsonb_build_object('id',m.jugador,'usuario',p.usuario,'personaje',p.personaje,'x',m.x,'z',m.z,'hambre',m.hambre,'energia',m.energia,'higiene',m.higiene,'diversion',m.diversion,'trabajos',m.trabajos,'accion',m.accion,'inicio',extract(epoch from m.inicio),'fin',extract(epoch from m.fin))) from public.miembros m join public.jugadores p on p.id=m.jugador where m.casa=c)) into r from public.casas h where h.id=c;return r;end;$$;
create or replace function public.nc_actividad(p_token text,p_accion text) returns boolean language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;h public.casas%rowtype;m public.miembros%rowtype;q public.miembros%rowtype;a public.acciones%rowtype;sx real;sz real;begin select casa into c from public.miembros where jugador=j;if c is null then raise exception 'Primero entra a tu casa.';end if;perform public.nc_tick(c);select * into h from public.casas where id=c for update;select * into m from public.miembros where jugador=j for update;select * into a from public.acciones where clave=p_accion;if a.clave is null then raise exception 'Actividad inválida.';end if;if m.accion is not null then raise exception 'Termina tu actividad.';end if;if h.dinero<a.costo then raise exception 'No alcanza el dinero de la casa.';end if;if p_accion='trabajo' and m.trabajos>=4 then raise exception 'Ya trabajaste cuatro veces hoy.';end if;if a.item is not null and not(h.compras ? a.item) and not(a.item='tv' and h.compras ? 'tvgrande') then raise exception 'Primero compra ese mueble.';end if;
if a.pareja then select * into q from public.miembros where casa=c and jugador<>j for update;if q.jugador is null or q.accion is not null or q.pos_actualizada<now()-interval '15 seconds' or sqrt(power(m.x-q.x,2)+power(m.z-q.z,2))>2.8 then raise exception 'Tu pareja debe estar cerca, conectada y libre.';end if;else select v.x,v.z into sx,sz from (values ('cama',-4::real,-2::real),('ducha',4,-3),('inodoro',6,-3),('nevera',-5,3),('cocinar',-3,3),('trabajo',0,5.5),('tv',3,1),('radio',6,1),('sofa',4,3),('patio',-7,0),('armario',-6,-3))v(k,x,z) where v.k=p_accion;if h.distribucion ? p_accion and p_accion<>'patio' then sx:=(h.distribucion->p_accion->>'x')::real;sz:=(h.distribucion->p_accion->>'z')::real;end if;if sx is not null and sqrt(power(m.x-sx,2)+power(m.z-sz,2))>2.2 then raise exception 'Acércate al objeto.';end if;end if;
update public.casas set dinero=dinero-a.costo where id=c;update public.miembros set accion=p_accion,inicio=now(),fin=now()+make_interval(secs=>a.segundos),pareja=false where jugador=j;if a.pareja then update public.miembros set accion=p_accion,inicio=now(),fin=now()+make_interval(secs=>a.segundos),pareja=true where jugador=q.jugador;end if;return true;end;$$;
create or replace function public.nc_mover_mueble(p_token text,p_item text,p_x real,p_z real) returns boolean language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;h public.casas%rowtype;defs jsonb:='{"cama":[-4,-2,1.4,1,-7,-0.4,-5,-0.1],"ducha":[4,-3,0.7,0.7,1.3,7,-5,-0.8],"inodoro":[6,-3,0.4,0.6,1.3,7,-5,-0.8],"nevera":[-5,3,0.55,0.55,-7,-1.2,1.3,5],"cocinar":[-3,3,0.75,0.6,-7,-1.2,1.3,5],"sofa":[4,3,1.5,0.7,1.3,7,0.1,5],"tv":[3,1,1.4,0.4,1.3,7,0.1,5],"radio":[6,1,0.45,0.3,1.3,7,0.1,5],"armario":[-6,-3,0.8,0.4,-7,-0.4,-5,-0.1],"planta":[6,4.5,0.45,0.45,1.3,7,0.1,5],"centro":[4,2,0.8,0.65,1.3,7,0.1,5],"comedor":[-2,4.5,0.8,1.3,-7,-1.2,1.3,5],"patio":[-8.5,0,0.8,0.65,-9.7,-7.3,-2,2],"lampara":[2,4,0.5,0.5,1.3,7,0.1,5],"lavamanos":[2,-4,0.5,0.4,1.3,7,-5,-0.8]}'::jsonb;d jsonb;b jsonb;q text;px real;pz real;begin
select casa into c from public.miembros where jugador=j;if c is null then raise exception 'Primero entra a tu casa.';end if;
select * into h from public.casas where id=c for update;
if exists(select 1 from public.miembros where casa=c and accion is not null) then raise exception 'Espera a que terminen las actividades.';end if;
if p_item is null or not(defs ? p_item) then raise exception 'Mueble inválido.';end if;
if not(p_item in ('cama','ducha','inodoro','nevera','cocinar') or h.compras ? p_item or (p_item='tv' and h.compras ? 'tvgrande')) then raise exception 'Compra primero ese mueble.';end if;
d:=defs->p_item;
if p_x is null or p_z is null or not(p_x between -10 and 8) or not(p_z between -6 and 6) or p_x*2<>round((p_x*2)::numeric) or p_z*2<>round((p_z*2)::numeric) then raise exception 'Posición inválida.';end if;
if p_x-(d->>2)::real<(d->>4)::real or p_x+(d->>2)::real>(d->>5)::real or p_z-(d->>3)::real<(d->>6)::real or p_z+(d->>3)::real>(d->>7)::real then raise exception 'Deja libres paredes, puertas y pasos.';end if;
for q,b in select key,value from jsonb_each(defs) loop
if q<>p_item and (q in ('cama','ducha','inodoro','nevera','cocinar') or h.compras ? q or (q='tv' and h.compras ? 'tvgrande')) then
px:=coalesce((h.distribucion->q->>'x')::real,(b->>0)::real);pz:=coalesce((h.distribucion->q->>'z')::real,(b->>1)::real);
if abs(p_x-px)<(d->>2)::real+(b->>2)::real+.15 and abs(p_z-pz)<(d->>3)::real+(b->>3)::real+.15 then raise exception 'Hay otro mueble en ese sitio.';end if;end if;end loop;
update public.casas set distribucion=jsonb_set(distribucion,array[p_item],jsonb_build_object('x',p_x,'z',p_z),true) where id=c;return true;end;$$;
revoke all on function public.nc_mover_mueble(text,text,real,real) from public;
grant execute on function public.nc_mover_mueble(text,text,real,real) to anon,authenticated;
notify pgrst,'reload schema';
commit;
